// This app rendered icons via Feather (287 names) until it switched to
// Lucide (Feather's actively-maintained fork, ~1900 names) so App Module
// Setting's icon field could use Frappe's native Icon-fieldtype picker
// (Lucide-based) instead of a bespoke one. Most Feather names carried over
// unchanged, but Lucide renamed roughly 45 of them during the fork - this
// is that rename map, generated by diffing Feather's name list against the
// Lucide sprite's symbol ids. Used both to keep any hardcoded Feather name
// still in this codebase rendering correctly, and (via the
// migrate_feather_icon_names_to_lucide patch) to rewrite names already
// stored in the database.
export const LEGACY_ICON_NAME_MAP = {
  'alert-circle': 'circle-alert',
  'alert-octagon': 'octagon-alert',
  'alert-triangle': 'triangle-alert',
  'align-center': 'align-horizontal-justify-center',
  'align-justify': 'text-align-justify',
  'align-left': 'align-horizontal-justify-start',
  'align-right': 'align-horizontal-justify-end',
  'arrow-down-circle': 'circle-arrow-down',
  'arrow-left-circle': 'circle-arrow-left',
  'arrow-right-circle': 'circle-arrow-right',
  'arrow-up-circle': 'circle-arrow-up',
  'bar-chart': 'chart-bar',
  'bar-chart-2': 'chart-bar-big',
  'check-circle': 'circle-check',
  'check-square': 'square-check',
  columns: 'columns-3',
  'divide-circle': 'circle-divide',
  'divide-square': 'square-divide',
  'download-cloud': 'cloud-download',
  edit: 'pencil',
  'edit-2': 'pencil',
  'edit-3': 'pen-line',
  filter: 'list-filter',
  'git-commit': 'git-commit-vertical',
  grid: 'grid-3x3',
  'help-circle': 'circle-question-mark',
  home: 'house',
  layout: 'layout-panel-left',
  'minus-circle': 'circle-minus',
  'minus-square': 'square-minus',
  'more-horizontal': 'ellipsis',
  'more-vertical': 'ellipsis-vertical',
  'pause-circle': 'circle-pause',
  'pie-chart': 'chart-pie',
  'play-circle': 'circle-play',
  'plus-circle': 'circle-plus',
  'plus-square': 'square-plus',
  sidebar: 'panel-left',
  sliders: 'sliders-vertical',
  'stop-circle': 'circle-stop',
  tool: 'wrench',
  unlock: 'lock-open',
  'upload-cloud': 'cloud-upload',
  'x-circle': 'circle-x',
  'x-octagon': 'octagon-x',
  'x-square': 'square-x',
}

export function toLucideIconName(name) {
  return LEGACY_ICON_NAME_MAP[name] || name
}
